import{_ as r,l as i,o as e,c as s,v as t,p as n,x as o,d as h,i as c,S as E}from"./chunks/framework.InCnrqk-.js";const M=JSON.parse('{"title":"随机性 Monte Carlo 仿真","description":"","frontmatter":{"title":"随机性 Monte Carlo 仿真","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/stochastic-monte-carlo.md","filePath":"litho/stochastic-monte-carlo.md","lastUpdated":1789023840000}'),d={name:"litho/stochastic-monte-carlo.md"};function p(C,a,m,u,B,_){const l=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="随机性-monte-carlo-仿真" tabindex="-1">随机性 Monte Carlo 仿真 <a class="header-anchor" href="#随机性-monte-carlo-仿真" aria-label="Permalink to &quot;随机性 Monte Carlo 仿真&quot;">​</a></h1><div class="epigraph"><p>连续 RD 给出平均轮廓；缺陷率问的是百万分之一的尾。要把光子、电子核、酸与碱抽样出来，均值方程不够。</p><footer>—— 据 Naulleau 等对随机抗蚀剂建模与重复曝光实验的公开框架整理</footer></div><p><a href="/litho/secondary-electron-blur-model">上一课</a>给出平均场可卷积的 \\(G_e\\)。缺口是实现离散：Monte Carlo 按泊松抽吸收，再抽电子/酸/碱，推进显影，统计边与失效。本课钉这套仿真该抽什么、如何对实验，不写某软件的输入卡。LER 的功率谱如何读 MC 输出，留给<a href="/litho/ler-psd">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/euv-stochastics">随机效应</a> 的缺陷是极值。平均场阈值模型没有尾部。MC 的最小内容：（1）按局部剂量抽吸收事件；（2）每个事件用 \\(G_e\\) 放酸；（3）预置碱位置（随机或团聚）；（4）PEB 中和与扩散可用随机行走或核；（5）显影用 \\(R\\) 或阈值。重复许多次，得 CD 分布、LER 实现、桥/断指示。</p><p>缺口不是再定义泊松，而是：哪些自由度必须抽，哪些可以留在核里。网格上给连续 \\(h\\) 再加白噪声，不是 MC——它忽略体积相关与分支过程，会把频谱抽错。</p><h3 id="要对的是重复曝光-不是掩模-ler" tabindex="-1">要对的是重复曝光，不是掩模 LER <a class="header-anchor" href="#要对的是重复曝光-不是掩模-ler" aria-label="Permalink to &quot;要对的是重复曝光，不是掩模 LER&quot;">​</a></h3><p>同一掩模、同一场重复曝光，CD 仍跳的那部分才是本课对象。掩模边缘粗糙是固定图案，MC 若不把掩模冻结，会把 PPE 算进随机。Naulleau 的实验语法是这条对拍。</p><p><span class="marginnote">SEM 噪声也是一次「抽样」。MC 输出要对真几何或声明过的计量核；把 SEM 白噪声拟合进胶 MC，剂量一改就穿帮。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>收敛：缺陷率目标若是 \\(10^{-6}\\)，朴素抽样要海量晶圆。工程用：加大统计的局部窗口、重要性抽样、或先拟合 CD 分布再外推尾——外推必须声明分布族，高斯 \\(3\\sigma\\) 进不了 ppm。校准：先对平均 CD 与 Bossung（均值应回到 RD），再对 LCDU–剂量斜率，再对稀事件。只拟合 LWR 一个数，频谱和尾都会错。</p><p>计算预算：全芯片 MC 不可行。用在热区、孔阵列、资格胶。OPC 仍用均值紧凑模型，至多加随机感知的目标函数，而不是每碎片抽分子。</p>',12)),(e(),n(E,null,{default:o(()=>[c(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%20%2F%20%E5%90%B8%E6%94%B6%22%5D%20--%3E%20MC%5B%22%E6%8A%BD%E6%A0%B7%E5%85%89%E5%AD%90%E4%B8%8E%E5%8C%96%E5%AD%A6%22%5D%0A%20%20GE%5B%22Ge%20%2F%20Ga%22%5D%20--%3E%20MC%0A%20%20MC%20--%3E%20ENS%5B%22%E8%BD%AE%E5%BB%93%E7%B3%BB%E7%BB%BC%22%5D%0A%20%20ENS%20--%3E%20MEAN%5B%22%E5%9D%87%E5%80%BC%20%E2%86%92%20%E5%BA%94%E5%9B%9E%20RD%22%5D%0A%20%20ENS%20--%3E%20TAIL%5B%22LCDU%20%2F%20%E7%BC%BA%E9%99%B7%E5%B0%BE%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每个实现对应一张显影后边。边的系综均值应等于平均场轮廓，否则抽样或显影非线性实现有偏。方差来自光子与化学；相关来自核——下一课 PSD 就是这张相关的傅里叶读出。失效：局部有效酸低于阈值的连通域，表现为断线或未开孔；过连通表现为桥。MC 的价值是让「悬崖」可计算，而不是给出更好看的平均 CD。</p><p>分支：一个 92 eV 光子可产多酸，酸数方差可以大于泊松。忽略 Fano / 分支会低估尾。Kozawa 路径在 MC 里就是分支过程，不是把 \\(Y\\) 乘在均值上了事。</p><p><span class="marginnote">金属氧化物 MC 抽的是团簇吸收与配体事件，不是 PAG。换胶族等于换抽样对象，不能只改剂量标尺。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不发明未发表的截面文件名。不把实验室计量胶的 MC 参数写成 NXE 量产规格。下一课把 MC 边序列变成 PSD；没有谱，只报 \\(3\\sigma\\) LER，无法判断核有没有抽对。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MC 抽样光子、电子核、酸/碱（或团簇），输出轮廓系综与尾。</li><li>均值必须回到 RD；对拍用重复曝光不是掩模 LER。</li><li>白噪声加在连续 \\(h\\) 上不是随机胶模型。</li><li>全芯片不跑 MC；热区与资格才跑。</li><li>出处：Naulleau 随机建模与实验语法；主干 <a href="/litho/euv-stochastics">euv-stochastics</a>。</li></ul>',8))])}const A=r(d,[["render",p]]);export{M as __pageData,A as default};
